; Schism: Complacency plus feeding the growing edge, for CellHack2.  GENERATED by cells/gen_schism.py -- do not
; edit by hand.  Written with AI help.
;
; Paste this whole file into the site.  It has no org/bits/section/%include on purpose: the server
; prepends `bits 64 / org CODE_BASE / default rel / <cellhack.inc>` and runs `nasm -f bin`.
; CPU target: plain qemu64 (SSE2 only used; no VEX).  No memory reads or writes of the cell memory, no loops,
; no stack use.  Relies on: rax = 0 at entry (registers are reset before every call).
;
; Behaviour: Complacency's (cells/complacency.asm) with one new rule on the boxed path.
;   New rule: no enemy in the 5x5, no empty neighbour, energy >= 6: feed the first friend of UP, RIGHT, DOWN,
;   LEFT that has an empty neighbour.  With no such friend, or an enemy in the 5x5: Complacency's boxed path
;   (energy >= 16: feed the poorest friend under its limits; otherwise rest).
;
; Instruction counts per path (every executed instruction, including taken jumps and ret):
;   bite 5, refill 11, split e >= 16 11, split 5 <= e < 16 16, rest e < 5 17: Complacency's
;   rest, boxed, e < 6                                       17     Complacency 17
;   new feed (no enemy in the 5x5, a candidate friend)         32 to 48
;   rest, boxed, 6 <= e < 16, enemy in the 5x5                 27     Complacency 17
;   rest, boxed, 6 <= e < 16, no candidate                 up to 50   Complacency 17
;   Complacency's feed block, e >= 16, enemy in the 5x5: Complacency's count + 10 (longest 63)
;   Complacency's feed block, e >= 16, no enemy, no candidate: longest 86 (Complacency 53)

start:
	movdqu		xmm0, [rdi + VIEW_CELLS + VIEW_UP]	; view idx 7..22
	pcmpeqb		xmm0, [kEnemy]
	pmovmskb	ecx, xmm0			; bits 0 UP, 4 LEFT, 6 RIGHT, 10 DOWN
	or		al, [abs bite_tbl + rcx]	; rax = 0 at entry: al = eat action, ZF = no enemy
	jnz		EXIT_ADDR			; bite: leave through the return address

slow:						; 5 instructions so far
	movdqu		xmm1, [rdi + VIEW_CELLS + 6]	; view idx 6..21
	pcmpeqb		xmm1, [kRefill]			; empty neighbours, enemies beside/beyond them
	pmovmskb	ecx, xmm1			; mask 0..7607
	mov		al, [abs act_tbl + rcx]		; split to take (0 = no empty neighbour)
	cmp		sil, [abs thr_tbl + rcx]	; energy it needs (12 refill, 16 other, 255 boxed)
	jae		EXIT_ADDR			; refill / split: 11 instructions
	test		al, al
	jz		boxed
	cmp		esi, 5
	jb		rest
	ret					; split: no prey hold
rest:
	mov		al, ACT_REST
	ret
boxed:
	cmp		esi, 6
	jb		rest
	movdqu		xmm1, [rdi + VIEW_CELLS]	; view idx 0..15
	movdqu		xmm2, [rdi + VIEW_CELLS + 9]	; view idx 9..24
	pcmpeqb		xmm1, [kTwoLo]
	pcmpeqb		xmm2, [kTwoHi]
	por		xmm1, xmm2
	pmovmskb	edx, xmm1
	test		edx, edx
	jnz		fallback			; enemy in the 5x5
	movdqu		xmm1, [rdi + VIEW_CELLS + 6]	; view idx 6..21
	pcmpeqb		xmm1, [kZero]
	pmovmskb	edx, xmm1			; bit (idx - 6): empty
	cmp		byte [rdi + VIEW_CELLS + 7], CELL_FRIEND
	jne		.s_up
	test		edx, 0x0005
	jnz		feed_up
	cmp		byte [rdi + VIEW_CELLS + 2], CELL_EMPTY
	je		feed_up
.s_up:
	cmp		byte [rdi + VIEW_CELLS + 13], CELL_FRIEND
	jne		.s_right
	test		edx, 0x1104
	jnz		feed_right
.s_right:
	cmp		byte [rdi + VIEW_CELLS + 17], CELL_FRIEND
	jne		.s_down
	test		edx, 0x1400
	jnz		feed_down
	cmp		byte [rdi + VIEW_CELLS + 22], CELL_EMPTY
	je		feed_down
.s_down:
	cmp		byte [rdi + VIEW_CELLS + 11], CELL_FRIEND
	jne		.s_left
	test		edx, 0x0411
	jnz		feed_left
.s_left:
fallback:
	cmp		esi, 16
	jb		rest
	lea		r9d, [rsi - 4]		; limit: poorest friend <= e - 4 ...
	mov		r10d, 46
	cmp		esi, 47
	cmovae		r9d, r10d			; ... or <= 46 for a capped donor
	mov		r8d, 255			; poorest friend energy so far
	mov		eax, ACT_REST
	cmp		byte [rdi + VIEW_CELLS + 7], CELL_FRIEND	; up
	jne		.n_up
	movzx		ecx, byte [rdi + VIEW_ENERGIES + 7]
	cmp		ecx, r8d
	jae		.n_up
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_UP
.n_up:
	cmp		byte [rdi + VIEW_CELLS + 13], CELL_FRIEND	; right
	jne		.n_right
	movzx		ecx, byte [rdi + VIEW_ENERGIES + 13]
	cmp		ecx, r8d
	jae		.n_right
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_RIGHT
.n_right:
	cmp		byte [rdi + VIEW_CELLS + 17], CELL_FRIEND	; down
	jne		.n_down
	movzx		ecx, byte [rdi + VIEW_ENERGIES + 17]
	cmp		ecx, r8d
	jae		.n_down
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_DOWN
.n_down:
	cmp		byte [rdi + VIEW_CELLS + 11], CELL_FRIEND	; left
	jne		.n_left
	movzx		ecx, byte [rdi + VIEW_ENERGIES + 11]
	cmp		ecx, r8d
	jae		.n_left
	mov		r8d, ecx
	mov		al, ACT_FEED + DIR_LEFT
.n_left:
	cmp		r8d, r9d
	ja		rest				; no friend (255), or the poorest is above the limit
	ret					; al = ACT_FEED + direction

feed_up:
	mov		al, ACT_FEED + DIR_UP
	ret
feed_right:
	mov		al, ACT_FEED + DIR_RIGHT
	ret
feed_down:
	mov		al, ACT_FEED + DIR_DOWN
	ret
feed_left:
	mov		al, ACT_FEED + DIR_LEFT
	ret

; ---- constants (legacy-SSE memory operands must be 16-byte aligned)
	align 16
kEnemy:	db 0x02, 0xff, 0xff, 0xff, 0x02, 0xff, 0x02, 0xff, 0xff, 0xff, 0x02, 0xff, 0xff, 0xff, 0xff, 0xff	; 2 at UP/LEFT/RIGHT/DOWN lanes (window idx 7..22)
kRefill:	db 0x02, 0x00, 0x02, 0xff, 0x02, 0x00, 0xff, 0x00, 0x02, 0xff, 0x02, 0x00, 0x02, 0xff, 0xff, 0xff	; window idx 6..21: 0 at neighbours, 2 at 6/8/10/14/16/18
kTwoLo:	db 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0xff, 0x02, 0x02, 0x02	; idx 0..15, self (lane 12) excluded
kTwoHi:	db 0x02, 0x02, 0x02, 0xff, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02, 0x02	; idx 9..24, self (lane 3) excluded
kZero:	times 16 db 0

